\thlabel{th:main}
Let $M\subset\mathbb{R}^N$ be a closed $C^{1,1}$ submanifold of dimension $1\leq m\leq N-1$. If $n=N-m$ then
\begin{align}
    \lim_{\rho\to0^+}\rho^{s-n}\operatorname{Per}_s^N(M_\rho)
    =\operatorname{Per}_s^n(B_1^n)\,\text{\usefont{OMS}{cmsy}{m}{n}H} ^m(M).\label{eq:thm-main}
\end{align}

\thlabel{cor:pointsets}
Let $P\geq2$ be an integer and let $M=\{a_1,\dots,a_P\}$ consist of pairwise distinct points of $\mathbb{R}^N$. Then, for $0<\rho<\frac12\min_{i\neq j}\vert a_i-a_j\vert$,
\begin{align}\label{eq:cor:pointsets}
    \operatorname{Per}_s^N(M_\rho)
    ={}&\operatorname{Per}_s^N(B_1^N)\text{\usefont{OMS}{cmsy}{m}{n}H} ^0(M)\rho^{N-s}\\
    &-\gamma(N,s)\big(\text{\usefont{OMS}{cmsy}{m}{n}H} ^N(B_1^N)\big)^2\rho^{2N}
    \sum_{\substack{1\leq i,j\leq P\\i\neq j}}
    \vert a_i-a_j\vert^{-(N+s)}
    {}_3F_2\!\left(\begin{matrix}
    \frac{N+s}{2},\ 1+\frac{s}{2},\ \frac{N+1}{2}\\
    \frac N2+1,\ N+1
    \end{matrix};\frac{4\rho^2}{\vert a_i-a_j\vert^2}\right).\nonumber
\end{align}
Here ${}_3F_2$ denotes the generalised hypergeometric function.

\thlabel{4gkQqROo} Let \(M\subset \mathbb{R}^N\) be a closed \(C^{1,1}\) submanifold of dimension \(m\) with \(1\leq m \leq N-1\) and let \(n=N-m\). Then there exist functions \(c_i \in L^\infty(N^1M)\) (depending on \(M\)) for \(i=0,\dots,m\) such that for all non-negative measurable functions \(h:\mathbb{R}^N \to \mathbb{R}\) and all \(0<\rho < \operatorname{reach}(M)\), we have
\begin{align*}
    \int_{M_\rho} h(z) \mathop{}\!\mathrm d \text{\usefont{OMS}{cmsy}{m}{n}H} ^N_z &= \sum_{i=0}^m\int_0^\rho \int_M \int_{N_x^1M} h(x+t\nu) t^{n-1+i} c_i(x,\nu) \mathop{}\!\mathrm d \text{\usefont{OMS}{cmsy}{m}{n}H} ^{n-1}_\nu \mathop{}\!\mathrm d \text{\usefont{OMS}{cmsy}{m}{n}H} ^m_x \mathop{}\!\mathrm d t .
\end{align*}
Furthermore, \(c_0=1\).

\thlabel{HmhFO2hM} Let \(M\subset \mathbb{R}^N\) be a closed \(C^{1,1}\) manifold of dimension \(m\) with \(1\leq m\leq N-1\) and let \(n=N-m\). There exist \(R,\delta>0\), depending only on \(M\), such that the following holds. Suppose
\begin{align*}
    0<\rho<\delta, \qquad x\in M, \qquad \nu\in N_x^1M, \qquad \tau\in[0,1], \qquad t\in[1,R/\rho], \qquad j\in\{0,\dots,m\}.
\end{align*}
Define
\begin{align*}
 I_j^{(\rho)}(x,\nu,t,\tau) := \int_M \int_{N_y^1M} \frac{c_j(y,\eta)}{\vert x-y+\rho t\nu-\rho\tau\eta\vert^{N+s}}\mathop{}\!\mathrm d \text{\usefont{OMS}{cmsy}{m}{n}H} ^{n-1}_\eta\mathop{}\!\mathrm d \text{\usefont{OMS}{cmsy}{m}{n}H} ^m_y .
\end{align*}
Then, for \((t,\tau)\neq(1,1)\),
\begin{align}
    \big \vert I_j^{(\rho)}(x,\nu,t,\tau)\big \vert
    \leq C\bigg(\frac{1}{\rho^{n+s}}\int_{N_x^1M}\frac{\mathop{}\!\mathrm d \text{\usefont{OMS}{cmsy}{m}{n}H} ^{n-1}_\eta}{\vert t\nu-\tau\eta\vert^{n+s}}+1\bigg), \label{7qouPfas}
\end{align}
where \(C>0\) depends only on \(m\), \(n\), \(s\), and \(M\). Furthermore, for every \((t,\tau)\neq(1,1)\),
\begin{align}
    \lim_{\rho\to0^+}\rho^{n+s}I_0^{(\rho)}(x,\nu,t,\tau)
    &=\frac{\gamma(n,s)}{\gamma(N,s)}\int_{N_x^1M}\frac{\mathop{}\!\mathrm d \text{\usefont{OMS}{cmsy}{m}{n}H} ^{n-1}_\eta}{\vert t\nu-\tau\eta\vert^{n+s}}. \label{QylvaPee}
\end{align}

By translating and rotating, we may assume without loss of generality that \(x=0\in M\), that \(T_0M=\mathbb{R}^m\times\{0_n\}\), and that \(\nu=(0,\omega)\) for some \(\omega\in\mathbb{S}^{n-1}\). Due to the regularity and compactness assumptions on \(M\), there exists \(\varepsilon=\varepsilon(M)>0\) and \(u\in C^{1,1}_c(\mathbb{R}^m;\mathbb{R}^n)\) satisfying \(u(0)=0\), \(\nabla u(0)=0\), and \(\|\nabla u\|_{C^{0,1}(\mathbb{R}^m;\mathbb{R}^n)}\leq C(M)\) such that
\begin{align}
    M\cap B_\varepsilon = \{(y,u(y))\text{ s.t. }y\in\mathbb{R}^m\}\cap B_\varepsilon. \label{17EZvdE8}
\end{align}
Also, there exist \(\nu_k\in C^{0,1}_c(\mathbb{R}^m;\mathbb{R}^N)\), with~\(k=1,\dots,n\), such that \(\{\nu_k(y)\}_{k=1}^n\) is an orthonormal basis for \(N_{(y,u(y))}M\) for all \(y\in U_\varepsilon\), where \(U_\varepsilon\subset\mathbb{R}^m\) is the preimage of \(M\cap B_\varepsilon\) under the map \(y\mapsto(y,u(y))\). These functions can be chosen so that \([\nu_k]_{C^{0,1}(\mathbb{R}^m;\mathbb{R}^N)}\leq C(M)\) and \(\nu_k(0)=e_{m+k}\). Hence, if
\begin{align}
    \iota_{(y,u(y))}(\theta)=\sum_{k=1}^n\theta_k\nu_k(y), \qquad \theta\in\mathbb{S}^{n-1}, \label{iuKhv7XF}
\end{align}
then \(\iota_0(\theta)=(0,\theta)\).

Choose \(r_0\) with \(0<r_0<\operatorname{reach}(M)\). After taking \(\delta>0\) smaller if necessary, we may assume that \(2\delta<r_0\) and
\begin{align*}
    [\pi_M]_{C^{0,1}(M_{2\delta})}\leq \frac{r_0}{r_0-2\delta}\leq2,
\end{align*}
where \(\pi_M\) denotes the nearest-point projection onto \(M\), see \cite[Theorem 4.8]{federer_curvature_1959}. Consider the map \(\psi:M_{2\delta}\to\mathbb{R}^N\times\mathbb{R}^N\) defined by
\begin{align*}
    \psi(z)=(\pi_M(z),z-\pi_M(z)).
\end{align*}
Then, for all \(z,\tilde z\in M_{2\delta}\),
\begin{align*}
    \vert\psi(z)-\psi(\tilde z)\vert^2
    &\leq \big([\pi_M]_{C^{0,1}(M_{2\delta})}^2+(1+[\pi_M]_{C^{0,1}(M_{2\delta})})^2\big)\vert z-\tilde z\vert^2
    \leq16\vert z-\tilde z\vert^2.
\end{align*}
In particular,
\begin{align}
    \vert\psi(z)-\psi(\tilde z)\vert\leq4\vert z-\tilde z\vert \qquad\text{for all }z,\tilde z\in M_{2\delta}. \label{1ZSP6tEk}
\end{align}

We split \(I_j^{(\rho)}\) into a local and a nonlocal part,
\begin{align*}
    I_j^{(\rho)}=J_j^{(\rho)}+\widetilde J_j^{(\rho)},
\end{align*}
where, using the local normal trivialisation above,
\begin{align*}
    J_j^{(\rho)}
    &=\int_{U_\varepsilon}\int_{\mathbb{S}^{n-1}}
    \frac{c_j((y,u(y)),\iota_{(y,u(y))}(\theta))J(y)}{\vert-(y,u(y))+\rho t(0,\omega)-\rho\tau\iota_{(y,u(y))}(\theta)\vert^{N+s}}
    \mathop{}\!\mathrm d\text{\usefont{OMS}{cmsy}{m}{n}H} ^{n-1}_\theta\mathop{}\!\mathrm d\text{\usefont{OMS}{cmsy}{m}{n}H} ^m_y,
\end{align*}
and \(\widetilde J_j^{(\rho)}\) is the corresponding integral over \(M\setminus B_\varepsilon\). Here
\begin{align*}
    J(y)=\sqrt{\det(I_m+(\nabla u)^T\nabla u)}
\end{align*}
is the Jacobian of the graph parametrisation.

We claim that, if \(0<R<\delta\), then
\begin{align}
\frac{1}{\vert-(y,u(y))+\rho t(0,\omega)-\rho\tau\iota_{(y,u(y))}(\theta)\vert^{N+s}}
\leq\frac{C}{\big(\vert y\vert^2+\rho^2\vert t\omega-\tau\theta\vert^2\big)^{\frac{N+s}{2}}}. \label{rbUDtvCD}
\end{align}
Indeed, set \(z=\rho t(0,\omega)\) and \(\tilde z=(y,u(y))+\rho\tau\iota_{(y,u(y))}(\theta)\). The assumptions imply that \(z,\tilde z\in M_{2\delta}\), and
\begin{align*}
    \psi(z)&=(0,\rho t(0,\omega)),\\
    \psi(\tilde z)&=((y,u(y)),\rho\tau\iota_{(y,u(y))}(\theta)).
\end{align*}
Thus, by~\eqref{1ZSP6tEk},
\begin{align}
    4\vert-(y,u(y))+\rho t(0,\omega)-\rho\tau\iota_{(y,u(y))}(\theta)\vert
    &\geq\sqrt{\vert(y,u(y))\vert^2+\rho^2\vert t(0,\omega)-\tau\iota_{(y,u(y))}(\theta)\vert^2}. \label{G2uT2ZXv}
\end{align}
Moreover, recalling~\eqref{iuKhv7XF},
\begin{align*}
    t(0,\omega)-\tau\iota_{(y,u(y))}(\theta)
    &=(0,t\omega-\tau\theta)+\tau\sum_{k=1}^n\theta_k(e_{m+k}-\nu_k(y)).
\end{align*}
Consequently, using the Lipschitz bounds on \(\nu_k\) and Young's inequality,
\begin{align*}
    \vert t(0,\omega)-\tau\iota_{(y,u(y))}(\theta)\vert^2
    &\geq\frac12\vert t\omega-\tau\theta\vert^2-C\vert y\vert^2.
\end{align*}
Hence, after taking \(\delta\) smaller if necessary,
\begin{align}
\vert y\vert^2+\rho^2\vert t(0,\omega)-\tau\iota_{(y,u(y))}(\theta)\vert^2
&\geq C\big(\vert y\vert^2+\rho^2\vert t\omega-\tau\theta\vert^2\big). \label{IJkD3qGG}
\end{align}
Combining~\eqref{G2uT2ZXv} and~\eqref{IJkD3qGG} gives~\eqref{rbUDtvCD}.

Using~\eqref{rbUDtvCD}, the boundedness of \(c_j\), and the bound \(\vert J\vert\leq C(M)\), we obtain
\begin{align*}
    \vert J_j^{(\rho)}\vert
    &\leq C\int_{\mathbb{S}^{n-1}}\int_{\mathbb{R}^m}\frac{\mathop{}\!\mathrm d\text{\usefont{OMS}{cmsy}{m}{n}H} ^m_y\mathop{}\!\mathrm d\text{\usefont{OMS}{cmsy}{m}{n}H} ^{n-1}_\theta}{\big(\vert y\vert^2+\rho^2\vert t\omega-\tau\theta\vert^2\big)^{\frac{N+s}{2}}}\\
    &\leq \frac{C}{\rho^{n+s}}\int_{\mathbb{S}^{n-1}}\frac{\mathop{}\!\mathrm d\text{\usefont{OMS}{cmsy}{m}{n}H} ^{n-1}_\theta}{\vert t\omega-\tau\theta\vert^{n+s}}.
\end{align*}
Since the identification \(\theta\mapsto(0,\theta)\) is an isometry from \(\mathbb{S}^{n-1}\) onto \(N_0^1M\), this is the first term on the right-hand side of~\eqref{7qouPfas}.

For \(\widetilde J_j^{(\rho)}\), choose also \(R<\varepsilon/2\) and \(\delta<\varepsilon/4\). If \(y\in M\setminus B_\varepsilon\), then
\begin{align*}
    \vert-y+\rho t(0,\omega)-\rho\tau\eta\vert\geq\vert y\vert-\rho t-\rho\tau\geq\varepsilon-R-\rho\geq\frac14\varepsilon,
\end{align*}
for every \(\eta\in N_y^1M\). Since \(M\) is compact and \(c_j\in L^\infty(N^1M)\), it follows that
\begin{align}
    \vert\widetilde J_j^{(\rho)}\vert\leq C. \label{W4jTZAat}
\end{align}
This proves~\eqref{7qouPfas}.

Finally, we prove~\eqref{QylvaPee}. Since \(c_0=1\), the change of variables \(y\mapsto\rho y\) gives
\begin{align*}
    \rho^{n+s}I_0^{(\rho)}
    &=\int_{U_\varepsilon/\rho}\int_{\mathbb{S}^{n-1}}
    \frac{J(\rho y)}{\vert-(y,\rho^{-1}u(\rho y))+t(0,\omega)-\tau\iota_{(\rho y,u(\rho y))}(\theta)\vert^{N+s}}
    \mathop{}\!\mathrm d\text{\usefont{OMS}{cmsy}{m}{n}H} ^{n-1}_\theta\mathop{}\!\mathrm d\text{\usefont{OMS}{cmsy}{m}{n}H} ^m_y+O(\rho^{n+s}).
\end{align*}
Rescaling the pointwise estimate~\eqref{rbUDtvCD}, we have
\begin{align*}
    &\frac{\vert J(\rho y)\chi_{U_\varepsilon/\rho}(y)\vert}{\vert-(y,\rho^{-1}u(\rho y))+t(0,\omega)-\tau\iota_{(\rho y,u(\rho y))}(\theta)\vert^{N+s}}\\
    &\hspace{8em}\leq\frac{C}{\big(\vert y\vert^2+\vert t\omega-\tau\theta\vert^2\big)^{\frac{N+s}{2}}}.
\end{align*}
For \((t,\tau)\neq(1,1)\), the right-hand side belongs to \(L^1(\mathbb{R}^m\times\mathbb{S}^{n-1})\). Moreover, for every fixed \(y\),
\begin{align*}
    \rho^{-1}u(\rho y)\to0, \qquad J(\rho y)\to1, \qquad \iota_{(\rho y,u(\rho y))}(\theta)\to(0,\theta).
\end{align*}
Therefore, the dominated convergence theorem gives
\begin{align}
    \lim_{\rho\to0^+}\rho^{n+s}I_0^{(\rho)}
    &=\int_{\mathbb{S}^{n-1}}\int_{\mathbb{R}^m}\frac{\mathop{}\!\mathrm d\text{\usefont{OMS}{cmsy}{m}{n}H} ^m_y\mathop{}\!\mathrm d\text{\usefont{OMS}{cmsy}{m}{n}H} ^{n-1}_\theta}{\big(\vert y\vert^2+\vert t\omega-\tau\theta\vert^2\big)^{\frac{N+s}{2}}}
    =\frac{\gamma(n,s)}{\gamma(N,s)}\int_{\mathbb{S}^{n-1}}\frac{\mathop{}\!\mathrm d\text{\usefont{OMS}{cmsy}{m}{n}H} ^{n-1}_\theta}{\vert t\omega-\tau\theta\vert^{n+s}}, \label{eq:limit-I0}
\end{align}
where in the last line we used
\begin{align*}
    \int_{\mathbb{R}^m}\frac{\mathop{}\!\mathrm d\text{\usefont{OMS}{cmsy}{m}{n}H} ^m_y}{(\vert y\vert^2+a^2)^{\frac{N+s}{2}}}
    =\frac{\gamma(n,s)}{\gamma(N,s)}a^{-n-s}, \qquad a>0.
\end{align*}
Identifying \(N_0^1M\) with \(\mathbb{S}^{n-1}\) proves~\eqref{QylvaPee}.

Let \(R,\delta>0\) be as in \thref{HmhFO2hM}. After possibly taking them smaller, assume that \(0<\delta<R<\operatorname{reach}(M)\). Then, for all \(0<\rho<\delta\),
\begin{align*}
\gamma(N,s)^{-1}\operatorname{Per}_s^N(M_\rho)
&=\int_{\mathbb{R}^N\setminus M_\rho}\int_{M_\rho}\frac{\mathop{}\!\mathrm d y\mathop{}\!\mathrm d x}{\vert x-y\vert^{N+s}}
=I_1(\rho)+I_2(\rho),
\end{align*}
where
\begin{align*}
I_1(\rho)&=\int_{\mathbb{R}^N\setminus M_R}\int_{M_\rho}\frac{\mathop{}\!\mathrm d y\mathop{}\!\mathrm d x}{\vert x-y\vert^{N+s}},\\
I_2(\rho)&=\int_{M_R\setminus M_\rho}\int_{M_\rho}\frac{\mathop{}\!\mathrm d y\mathop{}\!\mathrm d x}{\vert x-y\vert^{N+s}}.
\end{align*}

For \(I_1(\rho)\), we claim that
\begin{align}
I_1(\rho)\leq C\rho^n \qquad\text{for all }0<\rho<\delta. \label{ybvOyJ8W}
\end{align}
Indeed, \thref{4gkQqROo} with \(h=1\) gives \(\vert M_\rho\vert\leq C\rho^n\). Let \(\widetilde R>0\) be such that \(M\subset B_{\widetilde R/2}\). Then
\begin{align}
    I_1(\rho)
    &=\int_{B_{\widetilde R}\setminus M_R}\int_{M_\rho}\frac{\mathop{}\!\mathrm d y\mathop{}\!\mathrm d x}{\vert x-y\vert^{N+s}}
    +\int_{(\mathbb{R}^N\setminus M_R)\setminus B_{\widetilde R}}\int_{M_\rho}\frac{\mathop{}\!\mathrm d y\mathop{}\!\mathrm d x}{\vert x-y\vert^{N+s}}. \label{tJoywSjD}
\end{align}
Since \(\operatorname{dist}(\mathbb{R}^N\setminus M_R,M_\rho)=R-\rho\), the first integral is bounded by \(C\rho^n\). After taking \(\delta<\widetilde R/4\), we have \(M_\rho\subset B_{3\widetilde R/4}\), and therefore the second integral is also bounded by
\begin{align*}
    C\vert M_\rho\vert\int_{\mathbb{R}^N\setminus B_{\widetilde R}}\frac{\mathop{}\!\mathrm d x}{\vert x\vert^{N+s}}\leq C\rho^n.
\end{align*}
This proves~\eqref{ybvOyJ8W}; in particular, \(\rho^{s-n}I_1(\rho)\to0\).

For \(I_2(\rho)\), by \thref{4gkQqROo},
\begin{align*}
I_2(\rho)
&=\sum_{i,j=0}^m\int_\rho^R\int_M\int_{N_x^1M}\int_0^\rho\int_M\int_{N_y^1M}
\frac{t^{n-1+i}\tau^{n-1+j}c_i(x,\nu)c_j(y,\eta)}{\vert x-y+t\nu-\tau\eta\vert^{N+s}}\\
&\hspace{15em}\mathop{}\!\mathrm d\text{\usefont{OMS}{cmsy}{m}{n}H} ^{n-1}_\eta\mathop{}\!\mathrm d\text{\usefont{OMS}{cmsy}{m}{n}H} ^m_y\mathop{}\!\mathrm d\tau\mathop{}\!\mathrm d\text{\usefont{OMS}{cmsy}{m}{n}H} ^{n-1}_\nu\mathop{}\!\mathrm d\text{\usefont{OMS}{cmsy}{m}{n}H} ^m_x\mathop{}\!\mathrm d t.
\end{align*}
The changes of variables \(t\mapsto\rho t\) and \(\tau\mapsto\rho\tau\) yield
\begin{align*}
I_2(\rho)=\sum_{i,j=0}^m\rho^{2n+i+j}A_{ij}^{(\rho)},
\end{align*}
where
\begin{align*}
A_{ij}^{(\rho)}
&=\int_1^{R/\rho}\int_M\int_{N_x^1M}\int_0^1 t^{n-1+i}\tau^{n-1+j}c_i(x,\nu)I_j^{(\rho)}(x,\nu,t,\tau)\\
&\hspace{16em}\mathop{}\!\mathrm d\tau\mathop{}\!\mathrm d\text{\usefont{OMS}{cmsy}{m}{n}H} ^{n-1}_\nu\mathop{}\!\mathrm d\text{\usefont{OMS}{cmsy}{m}{n}H} ^m_x\mathop{}\!\mathrm d t.
\end{align*}
By~\eqref{7qouPfas} and the boundedness of \(c_i\),
\begin{align*}
\vert A_{ij}^{(\rho)}\vert
&\leq C\int_1^{R/\rho}\int_M\int_{N_x^1M}\int_0^1 t^{n-1+i}\tau^{n-1+j}
\bigg(\frac1{\rho^{n+s}}\int_{N_x^1M}\frac{\mathop{}\!\mathrm d\text{\usefont{OMS}{cmsy}{m}{n}H} ^{n-1}_\eta}{\vert t\nu-\tau\eta\vert^{n+s}}+1\bigg)\\
&\hspace{16em}\mathop{}\!\mathrm d\tau\mathop{}\!\mathrm d\text{\usefont{OMS}{cmsy}{m}{n}H} ^{n-1}_\nu\mathop{}\!\mathrm d\text{\usefont{OMS}{cmsy}{m}{n}H} ^m_x\mathop{}\!\mathrm d t.
\end{align*}
For each \(x\in M\), the fibre \(N_x^1M\) is isometric to \(\mathbb{S}^{n-1}\). Hence, by polar coordinates,
\begin{align*}
&\int_1^{R/\rho}\int_{N_x^1M}\int_0^1\int_{N_x^1M}
\frac{t^{n-1+i}\tau^{n-1+j}}{\rho^{n+s}\vert t\nu-\tau\eta\vert^{n+s}}
\mathop{}\!\mathrm d\text{\usefont{OMS}{cmsy}{m}{n}H} ^{n-1}_\eta\mathop{}\!\mathrm d\tau\mathop{}\!\mathrm d\text{\usefont{OMS}{cmsy}{m}{n}H} ^{n-1}_\nu\mathop{}\!\mathrm d t\\
&\leq\frac{R^i}{\rho^{n+s+i}}
\int_{\mathbb{R}^n\setminus B_1^n}\int_{B_1^n}\frac{\mathop{}\!\mathrm d\text{\usefont{OMS}{cmsy}{m}{n}H} ^n_y\mathop{}\!\mathrm d\text{\usefont{OMS}{cmsy}{m}{n}H} ^n_x}{\vert x-y\vert^{n+s}}
\leq C\rho^{-n-s-i}.
\end{align*}
Moreover,
\begin{align*}
\int_1^{R/\rho}\int_{N_x^1M}\int_0^1 t^{n-1+i}\tau^{n-1+j}\mathop{}\!\mathrm d\tau\mathop{}\!\mathrm d\text{\usefont{OMS}{cmsy}{m}{n}H} ^{n-1}_\nu\mathop{}\!\mathrm d t\leq C\rho^{-n-i}.
\end{align*}
Therefore,
\begin{align*}
    \vert A_{ij}^{(\rho)}\vert\leq C\rho^{-n-s-i}.
\end{align*}
It follows that
\begin{align}
\rho^{s-n}I_2(\rho)
=\sum_{i,j=0}^m\rho^{n+s+i+j}A_{ij}^{(\rho)}
=\sum_{i=0}^m\rho^{n+s+i}A_{i0}^{(\rho)}+O(\rho). \label{Li7JuxU0}
\end{align}

Since \(c_0=1\),
\begin{align*}
\rho^{n+s+i}A_{i0}^{(\rho)}
&=\int_1^{+\infty}\int_M\int_{N_x^1M}\int_0^1
\rho^{n+s+i}\chi_{[1,R/\rho]}(t)c_i(x,\nu)t^{n-1+i}\tau^{n-1}I_0^{(\rho)}(x,\nu,t,\tau)\\
&\hspace{17em}\mathop{}\!\mathrm d\tau\mathop{}\!\mathrm d\text{\usefont{OMS}{cmsy}{m}{n}H} ^{n-1}_\nu\mathop{}\!\mathrm d\text{\usefont{OMS}{cmsy}{m}{n}H} ^m_x\mathop{}\!\mathrm d t.
\end{align*}
By~\eqref{7qouPfas}, the absolute value of the integrand is bounded by
\begin{align*}
C\bigg(&R^i t^{n-1}\tau^{n-1}\int_{N_x^1M}\frac{\mathop{}\!\mathrm d\text{\usefont{OMS}{cmsy}{m}{n}H} ^{n-1}_\eta}{\vert t\nu-\tau\eta\vert^{n+s}}
+R^{n+s+i}t^{-1-s}\tau^{n-1}\bigg).
\end{align*}
This upper bound is integrable over
\begin{align*}
\Omega=\{(x,\nu,t,\tau):x\in M,\ \nu\in N_x^1M,\ t\in[1,+\infty),\ \tau\in[0,1]\},
\end{align*}
because its first term is a constant multiple of the fractional perimeter integral of \(B_1^n\) (see the computation below) and its second term is elementary.

Furthermore, by~\eqref{QylvaPee}, for almost every \((x,\nu,t,\tau)\in\Omega\),
\begin{align*}
&\lim_{\rho\to0^+}\rho^{n+s+i}\chi_{[1,R/\rho]}(t)c_i(x,\nu)t^{n-1+i}\tau^{n-1}I_0^{(\rho)}(x,\nu,t,\tau)\\
&\qquad=\frac{\gamma(n,s)}{\gamma(N,s)}\delta_{i0}t^{n-1}\tau^{n-1}
\int_{N_x^1M}\frac{\mathop{}\!\mathrm d\text{\usefont{OMS}{cmsy}{m}{n}H} ^{n-1}_\eta}{\vert t\nu-\tau\eta\vert^{n+s}}.
\end{align*}
Therefore, sending \(\rho\to0^+\) in~\eqref{Li7JuxU0} and applying the dominated convergence theorem, we obtain
\begin{align*}
\lim_{\rho\to0^+}\rho^{s-n}I_2(\rho)
&=\frac{\gamma(n,s)}{\gamma(N,s)}\int_M\int_{N_x^1M}\int_1^{+\infty}\int_0^1\int_{N_x^1M}
\frac{t^{n-1}\tau^{n-1}}{\vert t\nu-\tau\eta\vert^{n+s}}\\
&\hspace{16em}\mathop{}\!\mathrm d\text{\usefont{OMS}{cmsy}{m}{n}H} ^{n-1}_\eta\mathop{}\!\mathrm d\tau\mathop{}\!\mathrm d t\mathop{}\!\mathrm d\text{\usefont{OMS}{cmsy}{m}{n}H} ^{n-1}_\nu\mathop{}\!\mathrm d\text{\usefont{OMS}{cmsy}{m}{n}H} ^m_x\\
&=\frac{\gamma(n,s)}{\gamma(N,s)}\text{\usefont{OMS}{cmsy}{m}{n}H} ^m(M)
\int_{\mathbb{R}^n\setminus B_1^n}\int_{B_1^n}\frac{\mathop{}\!\mathrm d\text{\usefont{OMS}{cmsy}{m}{n}H} ^n_y\mathop{}\!\mathrm d\text{\usefont{OMS}{cmsy}{m}{n}H} ^n_x}{\vert x-y\vert^{n+s}}\\
&=\gamma(N,s)^{-1}\operatorname{Per}_s^n(B_1^n)\text{\usefont{OMS}{cmsy}{m}{n}H} ^m(M).
\end{align*}
Together with \(\rho^{s-n}I_1(\rho)\to0\), this proves \thref{th:main}.

\thlabel{lem:coarea}
    Let \(N\geq2\) and \(h:\mathbb{R} \to \mathbb{R}\) be a non-negative measurable function. Then \begin{align*}
        \int_{\partial B_1} h(x_1) \mathop{}\!\mathrm d \text{\usefont{OMS}{cmsy}{m}{n}H} ^{N-1}_x &=  \frac{2^{N-2} \text{\usefont{OMS}{cmsy}{m}{n}H} ^{N-1} \big (\partial B_1\big )}{\mathrm B\big (\frac{N-1}2 , \frac12 \big)}\int_0^1 h(1-2t) t^{ \frac{N-3}2   }(1-t)^{ \frac{N-3}2   }\mathop{}\!\mathrm d t
    \end{align*} where \(\mathrm B\) denotes the Beta function.

Let \(u:\mathbb{R}^N\to \mathbb{R}\) be defined by \(u(x)=x_1\). Then, on \(\partial B_1\), \(\vert \nabla_{\partial B_1}u(x)\vert  = \sqrt{1-x_1^2}\), so the co-area formula on \(\partial B_1\) yields \begin{align*}
        \int_{\partial B_1} h(x_1) \mathop{}\!\mathrm d \text{\usefont{OMS}{cmsy}{m}{n}H} ^{N-1}_x &= \int_{-1}^1 \int_{\partial B_1 \cap \{x_1=t\} } \frac{h(x_1)}{\sqrt{1-x_1^2}} \mathop{}\!\mathrm d \text{\usefont{OMS}{cmsy}{m}{n}H} ^{N-2}_x \mathop{}\!\mathrm d t \\
        &= \int_{-1}^1 \frac{h(t)}{\sqrt{1-t^2}}  \text{\usefont{OMS}{cmsy}{m}{n}H} ^{N-2} \big (\partial B_1 \cap \{x_1=t\}  \big ) \mathop{}\!\mathrm d t .
    \end{align*} Since \(\partial B_1 \cap \{x_1=t\}  = \{t\} \times \partial B^{N-1}_{\sqrt{1-t^2}}\), we obtain \begin{align*}
        \int_{\partial B_1} h(x_1) \mathop{}\!\mathrm d \text{\usefont{OMS}{cmsy}{m}{n}H} ^{N-1}_x &=  \text{\usefont{OMS}{cmsy}{m}{n}H} ^{N-2} \big (\partial B_1^{N-1}\big )\int_{-1}^1 h(t) \big(1-t^2 \big )^{ \frac{N-3}2   }\mathop{}\!\mathrm d t .
    \end{align*} Finally, the change of variable \(t\to 1-2t\) yields \begin{align*}
        \int_{\partial B_1} h(x_1) \mathop{}\!\mathrm d \text{\usefont{OMS}{cmsy}{m}{n}H} ^{N-1}_x &=  2^{N-2} \text{\usefont{OMS}{cmsy}{m}{n}H} ^{N-2} \big (\partial B_1^{N-1}\big )\int_0^1 h(1-2t) t^{ \frac{N-3}2   }(1-t)^{ \frac{N-3}2   }\mathop{}\!\mathrm d t \\
        &= \frac{2^{N-2} \text{\usefont{OMS}{cmsy}{m}{n}H} ^{N-1} \big (\partial B_1\big )}{\mathrm B\big (\frac{N-1}2 , \frac12 \big)}\int_0^1 h(1-2t) t^{ \frac{N-3}2   }(1-t)^{ \frac{N-3}2   }\mathop{}\!\mathrm d t
    \end{align*} as claimed, where the final equality follows from the identity \begin{align*}
        \mathrm B\bigg (\frac{N-1}2 , \frac12 \bigg) = \frac{\Gamma \big ( \frac {N-1} 2 \big )\pi^{1/2 }}{\Gamma \big ( \frac N2\big )} = \frac{2 \pi^{ N /2 }}{\Gamma \big ( \frac N2\big )} \cdot \frac{\Gamma \big ( \frac {N-1} 2 \big )}{ 2 \pi^{ \frac{N-1}2  } } = \frac{\text{\usefont{OMS}{cmsy}{m}{n}H} ^{N-1} \big (\partial B_1\big )}{\text{\usefont{OMS}{cmsy}{m}{n}H} ^{N-2} \big (\partial B_1^{N-1}\big )}.
    \end{align*}

\thlabel{prop:interaction-balls} Let \(\lambda > 2\) and \(\alpha \in \mathbb{R}\). Then \begin{align*}
    \int_{B_1}\int_{B_1(\lambda e_1)} \frac{\mathop{}\!\mathrm d y \mathop{}\!\mathrm d x }{\vert x-y\vert^\alpha } &= \big ( \text{\usefont{OMS}{cmsy}{m}{n}H} ^N(B_1)\big )^2 \lambda^{-\alpha} \cdot  {}_3 F_2 \bigg (
\begin{matrix}
\frac \alpha 2 , \frac{\alpha-N+2}2, \frac{N+1} 2\\
\frac N 2 +1 ,N+1 
\end{matrix}; \frac 4 {\lambda^2}
\bigg ).
\end{align*}

Here and throughout this proof, we use the notation \(\vert E \vert = \text{\usefont{OMS}{cmsy}{m}{n}H} ^N(E)\). Let \begin{align*}
        I= \int_{B_1}\int_{B_1(\lambda e_1)} \frac{\mathop{}\!\mathrm d y \mathop{}\!\mathrm d x }{\vert x-y\vert^\alpha }.
    \end{align*} By the change of variable \(y=x+\lambda e_1-z\) in the inner integral below, we have \begin{align*}
         I= \int_{B_1}\int_{B_1(\lambda e_1)} \frac{\mathop{}\!\mathrm d y \mathop{}\!\mathrm d x }{\vert x-y\vert^\alpha } &=  \int_{B_1} \int_{B_1(x )} \frac{\mathop{}\!\mathrm d z \mathop{}\!\mathrm d x }{\vert \lambda e_1-z \vert^\alpha }. 
    \end{align*} Furthermore, using that \begin{align*}
        \{ (x, z) \in \mathbb{R}^N \times \mathbb{R}^N \text{ s.t. } x\in B_1 , z\in B_1 (x) \} = \{ (x, z) \in \mathbb{R}^N \times \mathbb{R}^N \text{ s.t. } z\in B_2 , x\in B_1\cap  B_1 (z) \},
    \end{align*} Tonelli's theorem implies \begin{align*}
        I &=  \int_{B_2} \frac{\vert B_1 \cap B_1(z)\vert }{\vert \lambda e_1-z \vert^\alpha}  \mathop{}\!\mathrm d z . 
    \end{align*}  Since \(\vert B_1 \cap B_1(z)\vert = \vert B_1 \cap B_1( \vert z\vert e_1 )\vert  \), polar coordinates then imply \begin{align}
        I&=  \int_0^2 r^{N-1} \vert B_1 \cap B_1(r e_1 )\vert \bigg ( \int_{\partial B_1} \frac{\mathop{}\!\mathrm d \text{\usefont{OMS}{cmsy}{m}{n}H} ^{N-1}_\omega  }{\vert \lambda e_1-r \omega  \vert^\alpha}  \bigg )  \mathop{}\!\mathrm d r \label{eq:I}
    \end{align} Let \begin{align*}
        \text{\usefont{OMS}{cmsy}{m}{n}A}(r) = \int_{\partial B_1} \frac{\mathop{}\!\mathrm d \text{\usefont{OMS}{cmsy}{m}{n}H} ^{N-1}_\omega  }{\vert \lambda e_1-r \omega  \vert^\alpha}, \qquad r \in (0,2).  
    \end{align*} We claim that \begin{align}
        \text{\usefont{OMS}{cmsy}{m}{n}A}(r) &= \text{\usefont{OMS}{cmsy}{m}{n}H} ^{N-1} (\partial B_1) \lambda^{-\alpha} \cdot   {}_2 F_1 \bigg (\frac \alpha 2, \frac{\alpha-N+2}2 ;  \frac N2 ; \frac{r^2}{\lambda^2} \bigg )  . \label{eq:int-hypgeom}
    \end{align} Indeed, to prove the claim, we write \begin{align*}
        \text{\usefont{OMS}{cmsy}{m}{n}A}(r) = \int_{\partial B_1} \frac{\mathop{}\!\mathrm d \text{\usefont{OMS}{cmsy}{m}{n}H} ^{N-1}_\omega  }{\big ( \lambda ^2 + r^2 -2\lambda r \omega_1 \big )^ {\frac\alpha  2 }} = \lambda ^{-\alpha } \int_{\partial B_1} \frac{\mathop{}\!\mathrm d \text{\usefont{OMS}{cmsy}{m}{n}H} ^{N-1}_\omega  }{\big ( 1 + q^2 -2 q \omega_1 \big )^ {\frac\alpha  2 }} 
    \end{align*} where \(q=q(r) = r/\lambda \). Then, assuming \(N\geq 2\), \thref{lem:coarea} implies that \begin{align}
         \text{\usefont{OMS}{cmsy}{m}{n}A}(r)  &=\frac{2^{N-2} \text{\usefont{OMS}{cmsy}{m}{n}H} ^{N-1} \big (\partial B_1\big ) \lambda^{-\alpha} }{\mathrm B\big (\frac{N-1}2 , \frac12 \big)}\int_0^1 \frac{  t^{ \frac{N-3}2   }(1-t)^{ \frac{N-3}2   }}{ \big ( (1-q)^2 +4q t \big  )^{\alpha/2}} \mathop{}\!\mathrm d t . \label{eq:innerint}
    \end{align} Next, since \cite[Equation 15.6.1]{olver_nist_nodate} implies \begin{align}
        \int_0^1 \frac{  t^{ \frac{N-3}2   }(1-t)^{ \frac{N-3}2   }}{ \big ( (1-q)^2 +4q t \big  )^{\alpha/2}} \mathop{}\!\mathrm d t &= (1-q)^{-\alpha} \frac{\Gamma \big ( \frac{N-1}2 \big )^2  }{\Gamma(N-1)} \cdot {}_2 F_1 \bigg ( \frac \alpha 2 , \frac{N-1}2 ; N-1 ; \frac{-4q}{(1-q)^2} \bigg )  \label{eq:Hypgeom-identity}
    \end{align} and \begin{align*}
        \frac{2^{N-2} \text{\usefont{OMS}{cmsy}{m}{n}H} ^{N-1} \big (\partial B_1\big )}{\mathrm B\big (\frac{N-1}2 , \frac12 \big)} \cdot \frac{\Gamma \big ( \frac{N-1}2 \big )^2  }{\Gamma(N-1)} &= \frac{2^{N-1} \pi^{ \frac{N-1}2   } \Gamma \big ( \frac{N-1}2 \big )}{\Gamma(N-1)} = \frac{2 \pi^{N/2}}{\Gamma \big ( \frac N 2 \big  )} = \text{\usefont{OMS}{cmsy}{m}{n}H} ^{N-1} (\partial B_1)
    \end{align*} where the second equality follows from the Legendre duplication formula for the Gamma function, Equations~\eqref{eq:innerint} and~\eqref{eq:Hypgeom-identity} imply \begin{align*}
        \text{\usefont{OMS}{cmsy}{m}{n}A}(r) &=\text{\usefont{OMS}{cmsy}{m}{n}H} ^{N-1} (\partial B_1) \lambda^{-\alpha}(1-q)^{-\alpha} {}_2 F_1 \bigg ( \frac \alpha 2 , \frac{N-1}2 ; N-1 ; \frac{-4q}{(1-q)^2} \bigg ) . 
    \end{align*} Furthermore, by the quadratic transfomation (which follows from \cite[Equation 15.8.14]{olver_nist_nodate} and \cite[Equation 15.8.16]{olver_nist_nodate})\footnote{More explicitly, on one hand\cite[Equation 15.8.14]{olver_nist_nodate} gives \begin{align*}
        {}_2 F_1 \bigg (a,b ; 2b ; \frac{-4q}{(1-q)^2} \bigg ) = \bigg (  \frac{1-q}{1+q}\bigg )^a {}_2F_1 \bigg ( \frac a 2 , b - \frac a2 ; b + \frac12 ; \frac{-4q^2}{(1-q^2)^2} \bigg )
    \end{align*} since, if \(z=\frac{-4q}{(1-q)^2} \) then  \begin{align*}
        1-z = 1 - \bigg ( \frac{-4q}{(1-q)^2}\bigg  ) &= \bigg ( \frac{1+q}{1-q} \bigg )^2 \text{ and }\frac{z^2}{4(z-1)} = \frac{16 q^2}{(1-q)^4} \cdot  \frac{-(1-q)^2}{4(1+q)^2} = \frac{-4q^2}{(1-q^2)^2}.
    \end{align*} On the other hand, \cite[Equation 15.8.16]{olver_nist_nodate} gives \begin{align*}
        {}_2 F_1 \bigg (a,a-b+ \frac12 ; b + \frac12 ; q^2 \bigg ) &= \big (1-q^2)^{-a} {}_2 F_1 \bigg ( \frac a 2 , b - \frac a2  ; b+\frac12 ; \frac{-4q^2}{(1-q^2)^2} \bigg ). 
    \end{align*}Equating these identities yields the claimed quadratic transformation. 
} \begin{align*}
        {}_2 F_1 \bigg (a,b ; 2b ; \frac{-4q}{(1-q)^2} \bigg ) = (1-q)^{2a} {}_2 F_1 \bigg (a,a-b+ \frac12 ; b + \frac12 ; q^2 \bigg ),
    \end{align*} we obtain \begin{align*}
        \text{\usefont{OMS}{cmsy}{m}{n}A}(r) &=\text{\usefont{OMS}{cmsy}{m}{n}H} ^{N-1} (\partial B_1) \lambda^{-\alpha} \cdot   {}_2 F_1 \bigg (\frac \alpha 2, \frac{\alpha-N+2}2 ;  \frac N2 ; q^2 \bigg )
    \end{align*} Recalling that \(q=r/\lambda\), we obtain the claim~\eqref{eq:int-hypgeom}. The claim also holds when \(N=1\) since \begin{align*}
        \int_{\partial B_1} \frac{\mathop{}\!\mathrm d \text{\usefont{OMS}{cmsy}{m}{n}H} ^{0}_\omega }{ \big ( 1+q^2 -2q \omega_1 \big  )^{\alpha/2}}  &= \frac1{  ( 1-q )^\alpha}+\frac1{  ( 1+q )^\alpha} = 2 \cdot  {}_2 F_1 \bigg (\frac \alpha 2, \frac{\alpha+1}2 ;  \frac 12 ; q^2 \bigg ) 
    \end{align*} by \cite[Equation 15.4.7]{olver_nist_nodate}. 


    Next, we claim that \begin{align}
        \vert B_1 \cap B_1(re_1)\vert = 2 \text{\usefont{OMS}{cmsy}{m}{n}H} ^{N-1} \big ( B_1^{N-1} \big ) \int_{r/2}^1  \big (1-\rho^2\big )^{\frac{N-1}2   } \mathop{}\!\mathrm d \rho. \label{eq:volume}
    \end{align} provided \(r\in (0,2)\). Indeed, using symmetry then the coarea formula (in \(\mathbb{R}^N\)), we have \begin{align*}
        \vert B_1 \cap B_1(re_1)\vert &=2\vert B_1 \cap \{ x_1 > r/2 \}\vert  \\
        &= 2 \int_{r/2}^1 \text{\usefont{OMS}{cmsy}{m}{n}H} ^{N-1} ( B_1 \cap \{x_1=\rho\}  ) \mathop{}\!\mathrm d \rho \\
        &= 2 \text{\usefont{OMS}{cmsy}{m}{n}H} ^{N-1} \big ( B_1^{N-1} \big ) \int_{r/2}^1  \big (1-\rho^2\big )^{\frac{N-1}2   } \mathop{}\!\mathrm d \rho
    \end{align*} as claimed. 

In the final part of the proof we substitute~\eqref{eq:int-hypgeom} and~\eqref{eq:volume} into~\eqref{eq:I} to obtain \begin{align*}
    I &= 2  \text{\usefont{OMS}{cmsy}{m}{n}H} ^{N-1} \big ( B_1^{N-1} \big ) \text{\usefont{OMS}{cmsy}{m}{n}H} ^{N-1} \big ( \partial B_1 \big )    \lambda^{-\alpha}  \int_0^2\int_{r/2}^1  r^{N-1}\big (1-\rho^2\big )^{\frac{N-1}2   }   {}_2 F_1 \bigg (\frac \alpha 2, \frac{\alpha-N+2}2 ;  \frac N2 ; \frac{r^2}{\lambda^2} \bigg )  \mathop{}\!\mathrm d \rho \mathop{}\!\mathrm d r. 
\end{align*} Next, Tonelli's theorem implies \begin{align*}
    I &= 2 \text{\usefont{OMS}{cmsy}{m}{n}H} ^{N-1} \big ( B_1^{N-1} \big ) \text{\usefont{OMS}{cmsy}{m}{n}H} ^{N-1} \big ( \partial B_1 \big )   \lambda^{-\alpha}  \int_0^1 \big (1-\rho^2\big )^{\frac{N-1}2   } \int_0^{2\rho }  r^{N-1}   {}_2 F_1 \bigg (\frac \alpha 2, \frac{\alpha-N+2}2 ;  \frac N2 ; \frac{r^2}{\lambda^2} \bigg ) \mathop{}\!\mathrm d r \mathop{}\!\mathrm d \rho 
\end{align*} then the change of variable \(r=2\rho t^{1/2}\) yields \begin{align*}
    I &= 2^N \text{\usefont{OMS}{cmsy}{m}{n}H} ^{N-1} \big ( B_1^{N-1} \big ) \text{\usefont{OMS}{cmsy}{m}{n}H} ^{N-1} \big ( \partial B_1 \big )    \lambda^{-\alpha}  \int_0^1 \rho^N\big (1-\rho^2\big )^{\frac{N-1}2   }   \int_0^1  t^{ \frac N 2 -1}    {}_2 F_1 \bigg (\frac \alpha 2, \frac{\alpha-N+2}2 ;  \frac N2 ; \frac{ 4 \rho^2 t }{\lambda^2} \bigg ) \mathop{}\!\mathrm d t \mathop{}\!\mathrm d \rho 
\end{align*} Next, \cite[Equation 15.6.8]{olver_nist_nodate} implies \begin{align*}
     \int_0^1  t^{ \frac N 2 -1}    {}_2 F_1 \bigg (\frac \alpha 2, \frac{\alpha-N+2}2 ;  \frac N2 ; \frac{ 4 \rho^2 t }{\lambda^2} \bigg ) \mathop{}\!\mathrm d t &= \frac2 N {}_2 F_1 \bigg ( \frac \alpha 2, \frac{\alpha-N+2}2 ; \frac N2 +1 ;    \frac{ 4 \rho^2 }{\lambda^2}\bigg ), 
\end{align*} so, also using that  \(\text{\usefont{OMS}{cmsy}{m}{n}H} ^{N-1} \big ( \partial B_1 \big )= N \text{\usefont{OMS}{cmsy}{m}{n}H} ^N (B_1)\), \begin{align*}
    I &= \frac{2^{N+1}  \text{\usefont{OMS}{cmsy}{m}{n}H} ^{N-1} \big ( B_1^{N-1} \big ) \text{\usefont{OMS}{cmsy}{m}{n}H} ^{N-1} \big ( \partial B_1 \big )  \lambda^{-\alpha}} N   \int_0^1 \rho^N\big (1-\rho^2\big )^{\frac{N-1}2   } {}_2 F_1 \bigg ( \frac \alpha 2, \frac{\alpha-N+2}2 ; \frac N2 +1 ;    \frac{ 4 \rho^2 }{\lambda^2}\bigg )  \mathop{}\!\mathrm d \rho .
\end{align*} Finally, we apply the change of variable \(\rho \to \rho^{1/2}\) then \cite[Equation 16.5.2]{olver_nist_nodate} to conclude \begin{align*}
    I &= 2^{N}  \text{\usefont{OMS}{cmsy}{m}{n}H} ^{N-1} \big ( B_1^{N-1} \big )\text{\usefont{OMS}{cmsy}{m}{n}H} ^N (B_1) \lambda^{-\alpha}   \int_0^1 \rho^{\frac{N-1}2   }\big (1-\rho\big )^{\frac{N-1}2   } {}_2 F_1 \bigg ( \frac \alpha 2, \frac{\alpha-N+2}2 ; \frac N2 +1 ;    \frac{ 4 \rho }{\lambda^2}\bigg )  \mathop{}\!\mathrm d \rho \\
    &=  \frac{  2^{N}  \text{\usefont{OMS}{cmsy}{m}{n}H} ^{N-1} \big ( B_1^{N-1} \big ) \text{\usefont{OMS}{cmsy}{m}{n}H} ^N (B_1) \Gamma \big (\frac{N+1} 2 \big )^2 }{\Gamma (N+1)} \cdot \lambda^{-\alpha} \cdot  {}_3 F_2 \bigg (
\begin{matrix}
\frac \alpha 2 , \frac{\alpha-N+2}2, \frac{N+1} 2\\
\frac N 2 +1 ,N+1 
\end{matrix}; \frac 4 {\lambda^2}
\bigg ) \\ 
&=\big (\text{\usefont{OMS}{cmsy}{m}{n}H} ^N (B_1) \big )^2\lambda^{-\alpha} \cdot  {}_3 F_2 \bigg (
\begin{matrix}
\frac \alpha 2 , \frac{\alpha-N+2}2, \frac{N+1} 2\\
\frac N 2 +1 ,N+1 
\end{matrix}; \frac 4 {\lambda^2}
\bigg )
\end{align*} where in the final line we used that \( \text{\usefont{OMS}{cmsy}{m}{n}H} ^{N-1} \big ( B_1^{N-1} \big ) = \frac{\pi^{ \frac{N-1}2  } }{\Gamma \big ( \frac{N+1}2 \big )} \) and \(\Gamma(N+1)= 2^N \pi^{-1/2}\Gamma \big ( \frac{N+1}2 \big ) \Gamma \big ( \frac N2 +1 \big )\) (by the Legendre duplication formula) to obtain \begin{align}
   2^{N}  \text{\usefont{OMS}{cmsy}{m}{n}H} ^{N-1} \big ( B_1^{N-1} \big ) \cdot \frac{\Gamma \big (\frac{N+1} 2 \big )^2 }{\Gamma (N+1)} &= \frac{ \pi^{N/2} }{\Gamma \big ( \frac N2 +1\big )} = \text{\usefont{OMS}{cmsy}{m}{n}H} ^N  ( B_1 ) \label{eq:Gamma-calc}
\end{align}

For \(0<\rho<\frac 12 \min_{i\neq j}\vert a_i-a_j\vert\), the balls \(B_\rho(a_i)\) are pairwise disjoint and
\begin{align*}
    M_\rho=\bigcup_{i=1}^P\overline{B_\rho(a_i)},
\end{align*} so 
\begin{align*}
    \operatorname{Per}_s^N(M_\rho)
    &= \gamma(N,s) \sum_{i=1}^P \int_{\mathbb{R}^N\setminus M_\rho} \int_{B_\rho (a_i)} \frac{\mathop{}\!\mathrm d y \mathop{}\!\mathrm d x }{\vert x-y\vert^{N+s}}\\
    &=\sum_{i=1}^P\operatorname{Per}_s^N(B_\rho(a_i))
    -\gamma(N,s) \sum_{\stackrel{i,j=1}{i\neq j}}^P\int_{B_\rho(a_j)}\int_{B_\rho(a_i)}\frac{\mathop{}\!\mathrm d y \mathop{}\!\mathrm d x }{\vert x-y\vert^{N+s}}\\
    &=\operatorname{Per}_s^N(B_1)\text{\usefont{OMS}{cmsy}{m}{n}H} ^0(M) \rho^{N-s}
    -\gamma(N,s) \sum_{\stackrel{i,j=1}{i\neq j}}^P\int_{B_\rho(a_j)}\int_{B_\rho(a_i)}\frac{\mathop{}\!\mathrm d y \mathop{}\!\mathrm d x }{\vert x-y\vert^{N+s}}.
\end{align*} Then, by making the changes of variables \(x\to a_j+\rho x\), \(y\to a_j+\rho y\) and using rotational symmetry, we obtain \begin{align*}
    \int_{B_\rho(a_j)}\int_{B_\rho(a_i)}\frac{\mathop{}\!\mathrm d y \mathop{}\!\mathrm d x }{\vert x-y\vert^{N+s}} &= \rho^{N-s}\int_{B_1}\int_{B_1\big (\rho^{-1} (a_i-a_j) \big )}\frac{\mathop{}\!\mathrm d y \mathop{}\!\mathrm d x }{\vert x-y\vert^{N+s}}=\rho^{N-s}\int_{B_1}\int_{B_1\big (\rho^{-1} \vert a_i-a_j\vert e_1 \big )}\frac{\mathop{}\!\mathrm d y \mathop{}\!\mathrm d x }{\vert x-y\vert^{N+s}}. 
\end{align*} Finally, \thref{prop:interaction-balls} implies \begin{align*}
    \int_{B_\rho(a_j)}\int_{B_\rho(a_i)}\frac{\mathop{}\!\mathrm d y \mathop{}\!\mathrm d x }{\vert x-y\vert^{N+s}} &=\rho^{2N}\big ( \text{\usefont{OMS}{cmsy}{m}{n}H} ^N(B_1)\big )^2 \vert a_i-a_j\vert ^{-N-s} \cdot  {}_3 F_2 \bigg (
\begin{matrix}
\frac {N+s} 2 , \frac{s}2+1, \frac{N+1} 2\\
\frac N 2 +1 ,N+1 
\end{matrix}; \frac {4\rho^2} {\vert a_i-a_j\vert ^2}
\bigg )
\end{align*} completing the proof.

\thlabel{CC0og8h1}
    Let \(P\geq 2\) be an integer and \(M=\{a_1,\dots,a_P\}\) for pairwise distinct points \(a_1,\dots,a_P\in\mathbb{R}^N\). If \(K:\mathbb{R}^N\to\mathbb{R}\) is measurable, \(\operatorname{Per}_K(B)\) is finite for every ball \(B\subset\mathbb{R}^N\), and \(K\in C^\omega(\mathbb{R}^N\setminus\{0\})\), then there exists \(\rho_0>0\), depending on \(M\) and \(K\), such that
    \begin{align*}
        \operatorname{Per}_K(M_\rho)
        &=\operatorname{Per}_K(B_\rho)\text{\usefont{OMS}{cmsy}{m}{n}H} ^0(M)-\sum_{\stackrel{i,j=1}{i\neq j}}^P\sum_{\alpha\in\mathbb{N}_0^N}c_\alpha\partial^{2\alpha}K(a_j-a_i)\rho^{2N+2\vert\alpha\vert}
    \end{align*}
    for all \(0<\rho<\rho_0\), where
    \begin{align}
        c_\alpha=\big ( \text{\usefont{OMS}{cmsy}{m}{n}H} ^N(B_1) \big )^2  \cdot \frac{\big ( \frac{N+1}2 \big )_{\vert \alpha \vert }  }{ (N+1)_{\vert \alpha \vert } \cdot \big ( \frac N 2 +1\big )_{\vert \alpha \vert} \cdot \alpha! } .  \label{eq:c-alpha}
    \end{align}

For every \(i\neq j\), choose \(r_{ij}>0\) such that the Taylor series of \(K\) at \(a_j-a_i\) converges absolutely and uniformly on compact subsets of \(B_{r_{ij}}(a_j-a_i)\). Choose \(\rho_0>0\) so that
\begin{align*}
    2\rho_0<\min_{i\neq j}\min\{\vert a_i-a_j\vert,r_{ij}\}.
\end{align*}
Then, for \(0<\rho<\rho_0\), the balls \(B_\rho(a_i)\) are pairwise disjoint and
\begin{align*}
    M_\rho=\bigcup_{i=1}^P\overline{B_\rho(a_i)}.
\end{align*}
Consequently,
\begin{align*}
    \operatorname{Per}_K(M_\rho)
    &=\sum_{i=1}^P\operatorname{Per}_K(B_\rho(a_i))
    -\sum_{\stackrel{i,j=1}{i\neq j}}^P\int_{B_\rho(a_j)}\int_{B_\rho(a_i)}K(x-y)\mathop{}\!\mathrm d y\mathop{}\!\mathrm d x\\
    &=\operatorname{Per}_K(B_\rho)\text{\usefont{OMS}{cmsy}{m}{n}H} ^0(M)
    -\sum_{\stackrel{i,j=1}{i\neq j}}^P\int_{B_\rho(a_j)}\int_{B_\rho(a_i)}K(x-y)\mathop{}\!\mathrm d y\mathop{}\!\mathrm d x.
\end{align*}
For \(x\in B_\rho(a_j)\) and \(y\in B_\rho(a_i)\), we have
\begin{align*}
    x-y=(a_j-a_i)+\big(x-y-(a_j-a_i)\big),
\end{align*}
and \(\vert x-y-(a_j-a_i)\vert<2\rho<r_{ij}\). Thus the Taylor series at \(a_j-a_i\) may be integrated term by term:
\begin{align*}
\int_{B_\rho(a_j)}\int_{B_\rho(a_i)}K(x-y)\mathop{}\!\mathrm d y\mathop{}\!\mathrm d x
&=\sum_{\alpha\in\mathbb{N}_0^N}\frac{\partial^\alpha K(a_j-a_i)}{\alpha!}
\int_{B_\rho(a_j)}\int_{B_\rho(a_i)}\big(x-y-(a_j-a_i)\big)^\alpha\mathop{}\!\mathrm d y\mathop{}\!\mathrm d x.
\end{align*}
The changes of variables \(x=a_j+\rho X\) and \(y=a_i+\rho Y\) give
\begin{align*}
\int_{B_\rho(a_j)}\int_{B_\rho(a_i)}K(x-y)\mathop{}\!\mathrm d y\mathop{}\!\mathrm d x
&=\sum_{\alpha\in\mathbb{N}_0^N}\frac{\partial^\alpha K(a_j-a_i)}{\alpha!}\rho^{2N+\vert\alpha\vert}
\int_{B_1}\int_{B_1}(X-Y)^\alpha\mathop{}\!\mathrm d Y\mathop{}\!\mathrm d X.
\end{align*}
If any entry of \(\alpha\) is odd then the last integral vanishes by symmetry. Therefore,
\begin{align*}
\int_{B_\rho(a_j)}\int_{B_\rho(a_i)}K(x-y)\mathop{}\!\mathrm d y\mathop{}\!\mathrm d x
&=\sum_{\alpha\in\mathbb{N}_0^N}c_\alpha\partial^{2\alpha}K(a_j-a_i)\rho^{2N+2\vert\alpha\vert}
\end{align*} where \(c_\alpha\) is defined by \begin{align*}
     c_\alpha=\frac1{(2\alpha)!}\int_{B_1}\int_{B_1}(x-y)^{2\alpha}\mathop{}\!\mathrm d y\mathop{}\!\mathrm d x.
\end{align*} Finally, we show that \(c_\alpha\) has the form~\eqref{eq:c-alpha}. As at the start of the proof of~\thref{prop:interaction-balls}, we make the change of variable \(y=x-z\) in the inner integral, swap the order of integration, then use polar coordinates to obtain \begin{align*}
    c_\alpha &= \frac1{(2\alpha)!}\int_{B_1}\int_{B_1(x)} z^{2\alpha}\mathop{}\!\mathrm d z \mathop{}\!\mathrm d x \\
    &= \frac1{(2\alpha)!} \int_{B_2} \vert B_1 \cap B_1(z)\vert  z^{2\alpha}\mathop{}\!\mathrm d z \\
    &= \frac1{(2\alpha)!} \bigg ( \int_0^2 r^{N+2\vert \alpha\vert  -1} \vert B_1 \cap B_1(r e_1 )\vert \mathop{}\!\mathrm d r \bigg ) \bigg (  \int_{\partial B_1 }  \omega ^{2\alpha}\mathop{}\!\mathrm d \text{\usefont{OMS}{cmsy}{m}{n}H} ^{N-1}_\omega \bigg ) .
\end{align*} From \cite[Equation 12]{weyl_volume_1939}, we have \begin{align*}
    \int_{\partial B_1 }  \omega ^{2\alpha}\mathop{}\!\mathrm d \text{\usefont{OMS}{cmsy}{m}{n}H} ^{N-1}_\omega  &= \frac{\text{\usefont{OMS}{cmsy}{m}{n}H} ^{N-1}(\partial B_1) \prod_{\alpha_k\neq 0, k=1}^N (2\alpha_k - 1)!! }{(N+2\vert \alpha \vert -2) \cdots (N+2) N}. 
\end{align*} Then, using that \((2m-1)!! = \frac{(2m)!}{2^m m!}\), we have \begin{align*}
    \prod_{\alpha_k\neq 0, k=1}^N (2\alpha_k - 1)!! = \prod_{\alpha_k\neq 0, k=1}^N \frac{(2\alpha_k )!}{2^{\alpha_k} (\alpha_k)!} =\prod_{k=1}^N \frac{(2\alpha_k )!}{2^{\alpha_k} (\alpha_k)!} = \frac{(2\alpha)!}{2^{\vert \alpha \vert }\alpha! }
\end{align*} and \begin{align*}
    (N+2\vert \alpha \vert -2) \cdots (N+2) N = \frac{2^{\vert \alpha \vert } N }{N+ 2 \vert \alpha \vert } \cdot \bigg ( \frac N2 +\vert \alpha \vert \bigg  ) \cdots \bigg ( \frac N2 +1 \bigg ) = \frac{2^{\vert \alpha \vert } N }{N+ 2 \vert \alpha \vert } \bigg ( \frac N 2 +1\bigg )_{\vert \alpha \vert},
\end{align*} so \begin{align*}
    \int_{\partial B_1 }  \omega ^{2\alpha}\mathop{}\!\mathrm d \text{\usefont{OMS}{cmsy}{m}{n}H} ^{N-1}_\omega  &= \frac{ (N+2\vert \alpha \vert) \text{\usefont{OMS}{cmsy}{m}{n}H} ^{N-1}(\partial B_1) (2\alpha)!  }{2^{2\vert \alpha \vert } N  \cdot \big ( \frac N 2 +1\big )_{\vert \alpha \vert}\cdot  \alpha! }= \frac{ (N+2\vert \alpha \vert) \text{\usefont{OMS}{cmsy}{m}{n}H} ^N(B_1) (2\alpha)!  }{2^{2\vert \alpha \vert }   \big ( \frac N 2 +1\big )_{\vert \alpha \vert} \cdot \alpha! } . 
\end{align*} Furthermore, from~\eqref{eq:volume}, we have \begin{align*}
   \int_0^2 r^{N+2 \vert \alpha \vert  -1} \vert B_1 \cap B_1(r e_1 )\vert \mathop{}\!\mathrm d r &= 2 \text{\usefont{OMS}{cmsy}{m}{n}H} ^{N-1}\big ( B_1^{N-1} \big ) \int_0^2 \int_{r/2}^1r^{N+2 \vert \alpha \vert  -1}  (1-t^2)^{\frac{N-1}2} \mathop{}\!\mathrm d t \mathop{}\!\mathrm d r \\
   &=2 \text{\usefont{OMS}{cmsy}{m}{n}H} ^{N-1}\big ( B_1^{N-1} \big ) \int_0^1 \int_0^{2 t }r^{N+2 \vert \alpha \vert  -1}  (1-t^2)^{\frac{N-1}2} \mathop{}\!\mathrm d r  \mathop{}\!\mathrm d t \\
   &= \frac{2^{N+2\vert \alpha \vert +1} \text{\usefont{OMS}{cmsy}{m}{n}H} ^{N-1}\big ( B_1^{N-1} \big ) }{N+2\vert \alpha \vert }\int_0^1 t^{N+2 \vert \alpha \vert }  (1-t^2)^{\frac{N-1}2}  \mathop{}\!\mathrm d t .
\end{align*} Then the change of variable \(t\to t^{1/2}\) gives \begin{align*}
    \int_0^2 r^{N+2 \vert \alpha \vert  -1} \vert B_1 \cap B_1(r e_1 )\vert \mathop{}\!\mathrm d r &= \frac{2^{N+2\vert \alpha \vert } \text{\usefont{OMS}{cmsy}{m}{n}H} ^{N-1}\big ( B_1^{N-1} \big ) }{N+2\vert \alpha \vert }\int_0^1 t^{ \frac{N+2 \vert \alpha \vert-1}2  }  (1-t)^{\frac{N-1}2}  \mathop{}\!\mathrm d t \\
    &= \frac{2^{N+2\vert \alpha \vert } \text{\usefont{OMS}{cmsy}{m}{n}H} ^{N-1}\big ( B_1^{N-1} \big )  \Gamma \big ( \frac{N+2\vert \alpha \vert +1}2 \big )  \Gamma \big ( \frac{N+1}2 \big )  }{(N+2\vert \alpha \vert) \Gamma  (N+\vert \alpha \vert +1  )  }\\
    &= \frac{2^{N+2\vert \alpha \vert } \text{\usefont{OMS}{cmsy}{m}{n}H} ^{N-1}\big ( B_1^{N-1} \big )  \big ( \frac{N+1}2 \big )_{\vert \alpha \vert }  \cdot  \Gamma \big ( \frac{N+1}2 \big )  ^2 }{(N+2\vert \alpha \vert) (N+1)_{\vert \alpha \vert }\cdot  \Gamma  (N +1  )  } 
\end{align*} using the identities \(\int_0^1 t^{a-1}(1-t)^{b-1}\mathop{}\!\mathrm d t = \mathrm B(a,b) = \frac{\Gamma(a)\Gamma(b)}{\Gamma(a+b)}\) and \(\Gamma(x+k)=(x)_k \cdot \Gamma(x)\). Collecting the preceding identities, we obtain \begin{align*}
    c_\alpha &= \frac1{(2\alpha)!} \bigg ( \frac{2^{N+2\vert \alpha \vert } \text{\usefont{OMS}{cmsy}{m}{n}H} ^{N-1}\big ( B_1^{N-1} \big )  \big ( \frac{N+1}2 \big )_{\vert \alpha \vert }  \cdot  \Gamma \big ( \frac{N+1}2 \big )  ^2 }{(N+2\vert \alpha \vert) (N+1)_{\vert \alpha \vert }\cdot  \Gamma  (N +1  )  }  \bigg  )\bigg ( \frac{ (N+2\vert \alpha \vert) \text{\usefont{OMS}{cmsy}{m}{n}H} ^N(B_1) (2\alpha)!  }{2^{2\vert \alpha \vert }   \big ( \frac N 2 +1\big )_{\vert \alpha \vert} \cdot \alpha! }\bigg  )\\
    &=  \frac{2^{N } \text{\usefont{OMS}{cmsy}{m}{n}H} ^{N-1}\big ( B_1^{N-1} \big )\text{\usefont{OMS}{cmsy}{m}{n}H} ^N(B_1)     \cdot  \Gamma \big ( \frac{N+1}2 \big )  ^2 }{   \Gamma  (N +1  )  }  \cdot \frac{\big ( \frac{N+1}2 \big )_{\vert \alpha \vert }  }{ (N+1)_{\vert \alpha \vert } \cdot \big ( \frac N 2 +1\big )_{\vert \alpha \vert} \cdot \alpha! }.
\end{align*} Finally, using~\eqref{eq:Gamma-calc}, we obtain~\eqref{eq:c-alpha}, as desired.
